CREATE TABLE IF NOT EXISTS events (
  id TEXT PRIMARY KEY,
  primary_crime_type TEXT NOT NULL,
  crime_types TEXT[] NOT NULL DEFAULT ARRAY[]::text[],
  validation_status TEXT NOT NULL DEFAULT 'UNDER_REVIEW',
  priority TEXT NOT NULL DEFAULT 'MEDIUM',
  operation_name TEXT,
  occurred_at TIMESTAMPTZ,
  published_at TIMESTAMPTZ,
  added_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  backfill BOOLEAN NOT NULL DEFAULT FALSE,
  location_name TEXT,
  admin1 TEXT,
  country TEXT,
  lat DOUBLE PRECISION,
  lon DOUBLE PRECISION,
  location_precision TEXT,
  canonical_url TEXT UNIQUE,
  fingerprint TEXT NOT NULL UNIQUE,
  payload JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  modified_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS events_primary_crime_type_idx ON events(primary_crime_type);
CREATE INDEX IF NOT EXISTS events_validation_status_idx ON events(validation_status);
CREATE INDEX IF NOT EXISTS events_occurred_at_idx ON events(occurred_at DESC);
CREATE INDEX IF NOT EXISTS events_added_at_idx ON events(added_at DESC);
CREATE INDEX IF NOT EXISTS events_admin1_idx ON events(admin1);
CREATE INDEX IF NOT EXISTS events_country_idx ON events(country);
CREATE INDEX IF NOT EXISTS events_crime_types_gin_idx ON events USING GIN(crime_types);
CREATE INDEX IF NOT EXISTS events_payload_gin_idx ON events USING GIN(payload);

CREATE TABLE IF NOT EXISTS event_sources (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  publisher TEXT,
  url TEXT NOT NULL,
  published_at TIMESTAMPTZ,
  source_type TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(event_id, url)
);
CREATE INDEX IF NOT EXISTS event_sources_url_idx ON event_sources(url);

CREATE TABLE IF NOT EXISTS event_media (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  media_type TEXT NOT NULL DEFAULT 'image',
  url TEXT NOT NULL,
  credit TEXT,
  caption JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(event_id, url)
);

CREATE TABLE IF NOT EXISTS ingest_runs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source TEXT NOT NULL DEFAULT 'api',
  dry_run BOOLEAN NOT NULL DEFAULT FALSE,
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  finished_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'RUNNING',
  counts JSONB NOT NULL DEFAULT '{}'::jsonb,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb
);


INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-AM-2026-0914-PIRAAKAG','ILLEGAL_MINING',ARRAY['ILLEGAL_MINING','PROTECTED_AREA_INVASION']::text[],'CONFIRMED','HIGH','Pirá''ákãg','2026-07-13T23:59:00-04:00','2026-09-14T16:57:00-04:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Estação Ecológica Juami-Japurá','Amazonas','Brasil',-2.24222,-68.34896,'protected_area_centroid_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-e-icmbio-realizam-operacao-piraakag-de-combate-ao-garimpo-ilegal-em-manaus-am/','a6dc340e135845707be1a60cfe2a49ee8f6e2a0a3b2aa6a8db37083d42540679','{"id":"BR-AM-2026-0914-PIRAAKAG","title":{"pt":"Operação Pirá''ákãg combate garimpo ilegal na ESEC Juami-Japurá","en":"Operation Pirá''ákãg targets illegal mining in Juami-Japurá Ecological Station","es":"Operación Pirá''ákãg combate la minería ilegal en la ESEC Juami-Japurá"},"summary":{"pt":"PF e ICMBio informaram a apreensão ou inutilização de 11 dragas e diversos equipamentos usados no garimpo ilegal, além de cerca de 48 mil litros de combustível. Foram aplicadas multas ambientais que somaram R$ 1.622.800.","en":"Federal Police and ICMBio reported the seizure or disabling of 11 dredges and other equipment used in illegal mining, plus about 48,000 liters of fuel. Environmental fines totaled R$1,622,800.","es":"La Policía Federal e ICMBio informaron la incautación o inutilización de 11 dragas y otros equipos usados en minería ilegal, además de unos 48.000 litros de combustible. Las multas ambientales sumaron R$1.622.800."},"case_context":{"pt":"A ocorrência é especialmente relevante por estar dentro de uma unidade de conservação federal remota. A publicação ocorreu em setembro, mas a operação foi realizada entre 9 e 13 de julho; por isso, a data do evento e a data de publicação são mantidas separadas.","en":"The event is especially relevant because it occurred inside a remote federal protected area. Publication was in September, while the operation took place on July 9–13; event and publication dates are therefore kept separate.","es":"El evento es especialmente relevante por ocurrir dentro de una unidad de conservación federal remota. La publicación fue en septiembre, pero la operación ocurrió del 9 al 13 de julio; por eso se mantienen separadas las fechas del evento y de publicación."},"primary_crime_type":"ILLEGAL_MINING","crime_types":["ILLEGAL_MINING","PROTECTED_AREA_INVASION"],"operation_name":"Pirá''ákãg","agencies":["Polícia Federal","ICMBio"],"occurred_at":"2026-07-13T23:59:00-04:00","published_at":"2026-09-14T16:57:00-04:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official enforcement event; no inference of criminal guilt beyond what the cited source states.","priority":"HIGH","location":{"name":"Estação Ecológica Juami-Japurá","admin1":"Amazonas","country":"Brasil","lat":-2.24222,"lon":-68.34896,"precision":"protected_area_centroid_approximate"},"protected_area":{"is_protected_area":true,"name":"Estação Ecológica Juami-Japurá"},"impacts":{"indigenous_or_local_communities":false},"cross_border":false,"keywords":["dragas","ouro","combustível","Juami-Japurá"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-e-icmbio-realizam-operacao-piraakag-de-combate-ao-garimpo-ilegal-em-manaus-am/","published_at":"2026-09-14T16:57:00-04:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-e-icmbio-realizam-operacao-piraakag-de-combate-ao-garimpo-ilegal-em-manaus-am/whatsapp-image-2026-09-14-at-16-47-14.jpeg/@@images/0021aa19-49c4-41d2-9e64-19695910252c.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada na fonte oficial da Operação Pirá''ákãg.","en":"Image published by the official source for Operation Pirá''ákãg.","es":"Imagen publicada por la fuente oficial de la Operación Pirá''ákãg."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

