INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-RO-2026-0904-GUARDIAO-INFIEL','ILLEGAL_LOGGING',ARRAY['ILLEGAL_LOGGING','PROTECTED_AREA_INVASION']::text[],'CONFIRMED','HIGH','Guardião Infiel','2026-09-04T11:20:00-04:00','2026-09-04T11:20:00-04:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Terra Indígena Igarapé-Lage','Rondônia','Brasil',-11.3333,-65.0,'indigenous_land_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-faz-operacao-contra-exploracao-ilegal-de-madeira-em-terra-indigena','624ee96a8db33fb382b55d25ae0d39ae9470e89c13dc75fbe3849638ed477c15','{"id":"BR-RO-2026-0904-GUARDIAO-INFIEL","title":{"pt":"Operação Guardião Infiel apura exploração ilegal de madeira na TI Igarapé-Lage","en":"Operation Guardião Infiel investigates illegal logging in Igarapé-Lage Indigenous Land","es":"Operación Guardião Infiel investiga tala ilegal en la TI Igarapé-Lage"},"summary":{"pt":"A PF cumpriu sete mandados de busca e apreensão em investigação sobre extração e comercialização ilegal de madeira nativa da Terra Indígena Igarapé-Lage, em Guajará-Mirim.","en":"Federal Police executed seven search warrants in an investigation into the illegal extraction and sale of native timber from Igarapé-Lage Indigenous Land in Guajará-Mirim.","es":"La Policía Federal cumplió siete órdenes de allanamiento en una investigación sobre extracción y comercialización ilegal de madera nativa de la Tierra Indígena Igarapé-Lage, en Guajará-Mirim."},"case_context":{"pt":"A fonte oficial descreve uma investigação em curso e não uma condenação. O observatório registra a operação como evento confirmado e a conduta investigada como alegação oficial.","en":"The official source describes an ongoing investigation rather than a conviction. The observatory records the operation as a confirmed event and the investigated conduct as an official allegation.","es":"La fuente oficial describe una investigación en curso y no una condena. El observatorio registra la operación como evento confirmado y la conducta investigada como alegación oficial."},"primary_crime_type":"ILLEGAL_LOGGING","crime_types":["ILLEGAL_LOGGING","PROTECTED_AREA_INVASION"],"operation_name":"Guardião Infiel","agencies":["Polícia Federal"],"occurred_at":"2026-09-04T11:20:00-04:00","published_at":"2026-09-04T11:20:00-04:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official investigation; no inference of guilt.","priority":"HIGH","location":{"name":"Terra Indígena Igarapé-Lage","admin1":"Rondônia","country":"Brasil","lat":-11.3333,"lon":-65.0,"precision":"indigenous_land_approximate"},"protected_area":{"is_protected_area":true,"name":"Terra Indígena Igarapé-Lage"},"impacts":{"indigenous_or_local_communities":true},"cross_border":false,"keywords":["madeira","terra indígena","Guajará-Mirim"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-faz-operacao-contra-exploracao-ilegal-de-madeira-em-terra-indigena","published_at":"2026-09-04T11:20:00-04:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-faz-operacao-contra-exploracao-ilegal-de-madeira-em-terra-indigena/whatsapp-image-2026-09-04-at-11-11-09.jpeg/@@images/ffe98df3-21a0-47c8-9a46-0fe60511e176.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF na matéria da operação.","en":"Image published by Federal Police in the operation report.","es":"Imagen publicada por la Policía Federal en la nota de la operación."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

