INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-RO-2026-0903-ITERUM-IV','ILLEGAL_MINING',ARRAY['ILLEGAL_MINING','ENVIRONMENTAL_CONTAMINATION']::text[],'CONFIRMED','HIGH','Iterum IV','2026-09-03T14:26:00-04:00','2026-09-03T14:26:00-04:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Baixo Rio Madeira','Rondônia','Brasil',-8.65,-63.72,'regional_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-e-ibama-inutilizam-15-dragas-utilizadas-em-garimpo-ilegal-no-rio-madeira','017e6470159f5bea6eb8db86412ae22692e55d1396c882ea46f6658c342f624d','{"id":"BR-RO-2026-0903-ITERUM-IV","title":{"pt":"Operação Iterum IV inutiliza 15 dragas no baixo Rio Madeira","en":"Operation Iterum IV disables 15 dredges on the lower Madeira River","es":"Operación Iterum IV inutiliza 15 dragas en el bajo río Madeira"},"summary":{"pt":"PF e Ibama informaram a inutilização de 15 dragas e motores usados em garimpo ilegal e a apreensão de mercúrio e aparelhos celulares no baixo Rio Madeira, em Rondônia.","en":"Federal Police and Ibama reported disabling 15 dredges and engines used in illegal mining and seizing mercury and mobile phones on the lower Madeira River in Rondônia.","es":"La Policía Federal e Ibama informaron la inutilización de 15 dragas y motores usados en minería ilegal y la incautación de mercurio y teléfonos móviles en el bajo río Madeira, Rondônia."},"case_context":{"pt":"O uso de dragas e a apreensão de mercúrio tornam o caso relevante tanto para mineração ilegal quanto para risco de contaminação ambiental. A fonte também indica investigação sobre financiadores e executores.","en":"The use of dredges and seizure of mercury make the case relevant to both illegal mining and contamination risk. The source also notes investigation into financiers and operators.","es":"El uso de dragas y la incautación de mercurio hacen que el caso sea relevante tanto para minería ilegal como para riesgo de contaminación. La fuente también menciona investigaciones sobre financiadores y ejecutores."},"primary_crime_type":"ILLEGAL_MINING","crime_types":["ILLEGAL_MINING","ENVIRONMENTAL_CONTAMINATION"],"operation_name":"Iterum IV","agencies":["Polícia Federal","Ibama"],"occurred_at":"2026-09-03T14:26:00-04:00","published_at":"2026-09-03T14:26:00-04:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official enforcement event; no inference of guilt.","priority":"HIGH","location":{"name":"Baixo Rio Madeira","admin1":"Rondônia","country":"Brasil","lat":-8.65,"lon":-63.72,"precision":"regional_approximate"},"protected_area":{"is_protected_area":false},"impacts":{"indigenous_or_local_communities":false},"cross_border":false,"keywords":["Rio Madeira","dragas","mercúrio","ouro"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-e-ibama-inutilizam-15-dragas-utilizadas-em-garimpo-ilegal-no-rio-madeira","published_at":"2026-09-03T14:26:00-04:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/09/pf-e-ibama-inutilizam-15-dragas-utilizadas-em-garimpo-ilegal-no-rio-madeira/whatsapp-image-2026-09-03-at-14-18-06-2.jpeg/@@images/de60ac93-235d-44d8-94bc-70f269881298.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF na Operação Iterum IV.","en":"Image published by Federal Police for Operation Iterum IV.","es":"Imagen publicada por la Policía Federal para la Operación Iterum IV."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

