INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-PE-AM-2026-0831-PACHAMAMA','MULTIPLE_ENVIRONMENTAL_CRIMES',ARRAY['ILLEGAL_MINING','ILLEGAL_LOGGING','ILLEGAL_DEFORESTATION','WILDLIFE_CRIME','ENVIRONMENTAL_CONTAMINATION']::text[],'CONFIRMED','URGENT','Pachamama','2026-08-28T23:59:00-04:00','2026-08-31T18:17:00-04:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Tabatinga–Islândia border region','Amazonas / Loreto','Brasil / Peru',-4.231,-69.938,'regional_anchor','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-realiza-operacao-integrada-na-fronteira-entre-brasil-e-peru','5560b0a1188d36df4573a9f8adb4f0650fa54de30871ec3d76c05f73bdb1ab09','{"id":"BR-PE-AM-2026-0831-PACHAMAMA","title":{"pt":"Operação Pachamama realiza fiscalização ambiental na fronteira Brasil–Peru","en":"Operation Pachamama conducts environmental enforcement on the Brazil–Peru border","es":"Operación Pachamama realiza fiscalización ambiental en la frontera Brasil–Perú"},"summary":{"pt":"A operação binacional entre Tabatinga e Islândia/Peru fiscalizou mais de 300 pessoas, quatro serrarias e áreas de desmatamento; inutilizou oito dragas e apreendeu madeira, mercúrio, equipamentos e oito asas de mutum. Houve embargo de 126 hectares e mais de R$ 560 mil em multas.","en":"The binational operation between Tabatinga and Islandia, Peru inspected more than 300 people, four sawmills and deforestation areas; disabled eight dredges and seized timber, mercury, equipment and eight curassow wings. Authorities embargoed 126 hectares and issued over R$560,000 in fines.","es":"La operación binacional entre Tabatinga e Islandia, Perú fiscalizó a más de 300 personas, cuatro aserraderos y áreas deforestadas; inutilizó ocho dragas e incautó madera, mercurio, equipos y ocho alas de paujil. Se embargaron 126 hectáreas y se aplicaron más de R$560.000 en multas."},"case_context":{"pt":"É um evento multidelito e transfronteiriço, envolvendo mineração, madeira, fauna e desmatamento. O ponto no mapa representa a região operacional de Tabatinga, não todos os locais fiscalizados dentro do raio superior a 250 km descrito pela fonte.","en":"This is a multi-offense cross-border event involving mining, timber, wildlife and deforestation. The map point represents the Tabatinga operational area, not every location inspected within the source''s reported radius of more than 250 km.","es":"Es un evento transfronterizo de múltiples delitos, con minería, madera, fauna y deforestación. El punto del mapa representa el área operativa de Tabatinga y no todos los lugares fiscalizados dentro del radio superior a 250 km informado por la fuente."},"primary_crime_type":"MULTIPLE_ENVIRONMENTAL_CRIMES","crime_types":["ILLEGAL_MINING","ILLEGAL_LOGGING","ILLEGAL_DEFORESTATION","WILDLIFE_CRIME","ENVIRONMENTAL_CONTAMINATION"],"operation_name":"Pachamama","agencies":["Polícia Federal","Policía Nacional del Perú","Força Nacional","Polícia Militar do Amazonas","Ibama","Funai","CCPI-Amazônia"],"occurred_at":"2026-08-28T23:59:00-04:00","published_at":"2026-08-31T18:17:00-04:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official binational enforcement event; no inference of guilt.","priority":"URGENT","location":{"name":"Tabatinga–Islândia border region","admin1":"Amazonas / Loreto","country":"Brasil / Peru","lat":-4.231,"lon":-69.938,"precision":"regional_anchor"},"protected_area":{"is_protected_area":true,"name":"Multiple Indigenous and forest areas within the operation radius"},"impacts":{"indigenous_or_local_communities":true},"cross_border":true,"keywords":["madeira","mercúrio","dragas","mutum","desmatamento","fronteira"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-realiza-operacao-integrada-na-fronteira-entre-brasil-e-peru","published_at":"2026-08-31T18:17:00-04:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-realiza-operacao-integrada-na-fronteira-entre-brasil-e-peru/whatsapp-image-2026-08-31-at-18-05-45-2.jpeg/@@images/a4e72c20-bd95-447f-947e-95238e14dc63.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF durante a Operação Pachamama.","en":"Image published by Federal Police during Operation Pachamama.","es":"Imagen publicada por la Policía Federal durante la Operación Pachamama."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

