INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-RO-2026-0825-RIO-MEQUENS','ILLEGAL_LOGGING',ARRAY['ILLEGAL_LOGGING','PROTECTED_AREA_INVASION']::text[],'CONFIRMED','HIGH','Ação integrada na TI Rio Mequéns','2026-08-25T21:55:00-04:00','2026-08-25T21:55:00-04:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Terra Indígena Rio Mequéns','Rondônia','Brasil',-12.66,-61.72,'indigenous_land_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/policia-federal-realiza-acao-de-combate-a-extracao-ilegal-de-madeira-em-terra-indigena','6a4117667c18c263661da2600859da188779b800f0df8ca387e5e40c79df55d8','{"id":"BR-RO-2026-0825-RIO-MEQUENS","title":{"pt":"Ação combate extração ilegal de madeira na TI Rio Mequéns","en":"Operation targets illegal logging in Rio Mequéns Indigenous Land","es":"Acción combate la extracción ilegal de madera en la TI Rio Mequéns"},"summary":{"pt":"PF, Polícia Militar Ambiental, Força Nacional e Ibama inutilizaram duas serrarias móveis, uma motocicleta e um acampamento em pontos de exploração ilegal identificados por imagens de satélite dentro da Terra Indígena Rio Mequéns.","en":"Federal Police, Environmental Military Police, National Force and Ibama disabled two mobile sawmills, a motorcycle and a camp at illegal logging points identified by satellite imagery inside Rio Mequéns Indigenous Land.","es":"La Policía Federal, Policía Militar Ambiental, Fuerza Nacional e Ibama inutilizaron dos aserraderos móviles, una motocicleta y un campamento en puntos de explotación ilegal identificados por imágenes satelitales dentro de la Tierra Indígena Rio Mequéns."},"case_context":{"pt":"A fonte informa que a identificação dos pontos foi apoiada por imagens de satélite, um padrão de interesse para futura integração do observatório com camadas de alertas remotos.","en":"The source says the sites were identified using satellite imagery, a pattern relevant to future integration with remote-sensing alert layers.","es":"La fuente informa que los puntos fueron identificados con apoyo de imágenes satelitales, un patrón relevante para la futura integración con capas de alertas de teledetección."},"primary_crime_type":"ILLEGAL_LOGGING","crime_types":["ILLEGAL_LOGGING","PROTECTED_AREA_INVASION"],"operation_name":"Ação integrada na TI Rio Mequéns","agencies":["Polícia Federal","Polícia Militar Ambiental","Força Nacional","Ibama"],"occurred_at":"2026-08-25T21:55:00-04:00","published_at":"2026-08-25T21:55:00-04:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official enforcement event; no inference of guilt.","priority":"HIGH","location":{"name":"Terra Indígena Rio Mequéns","admin1":"Rondônia","country":"Brasil","lat":-12.66,"lon":-61.72,"precision":"indigenous_land_approximate"},"protected_area":{"is_protected_area":true,"name":"Terra Indígena Rio Mequéns"},"impacts":{"indigenous_or_local_communities":true},"cross_border":false,"keywords":["serraria móvel","madeira","satélite","terra indígena"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/policia-federal-realiza-acao-de-combate-a-extracao-ilegal-de-madeira-em-terra-indigena","published_at":"2026-08-25T21:55:00-04:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/policia-federal-realiza-acao-de-combate-a-extracao-ilegal-de-madeira-em-terra-indigena/whatsapp-image-2026-08-25-at-21-03-50.jpeg/@@images/6ff37857-f82b-4bf5-afc9-01d5eba45ec6.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF na ação da TI Rio Mequéns.","en":"Image published by Federal Police for the Rio Mequéns operation.","es":"Imagen publicada por la Policía Federal en la acción de la TI Rio Mequéns."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

