INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-PA-2026-0814-UKARANGMA','ILLEGAL_LOGGING',ARRAY['ILLEGAL_LOGGING','ILLEGAL_DEFORESTATION','LAND_GRABBING','PROTECTED_AREA_INVASION']::text[],'CONFIRMED','HIGH','Ukarãngmã','2026-08-13T16:50:00-03:00','2026-08-14T16:50:00-03:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Terra Indígena Cachoeira Seca','Pará','Brasil',-4.35,-52.37,'indigenous_land_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-cumpre-oito-mandados-de-busca-e-apreensao-em-terra-indigena','813d2f7b4c7e70a74859176ffc37b55b7b904f79351e9d1537d73735ee479135','{"id":"BR-PA-2026-0814-UKARANGMA","title":{"pt":"Operação Ukarãngmã combate desmatamento e madeira ilegal na TI Cachoeira Seca","en":"Operation Ukarãngmã targets deforestation and illegal logging in Cachoeira Seca Indigenous Land","es":"Operación Ukarãngmã combate deforestación y tala ilegal en la TI Cachoeira Seca"},"summary":{"pt":"A PF cumpriu oito mandados na Terra Indígena Cachoeira Seca. A investigação apontou pontos de extração ilegal, ramais clandestinos e rotas de escoamento de madeira; caminhões, maquinários e armas foram apreendidos.","en":"Federal Police executed eight warrants in Cachoeira Seca Indigenous Land. Investigators identified illegal extraction sites, clandestine roads and timber transport routes; trucks, machinery and firearms were seized.","es":"La Policía Federal cumplió ocho órdenes en la Tierra Indígena Cachoeira Seca. La investigación identificó puntos de extracción ilegal, caminos clandestinos y rutas de salida de madera; se incautaron camiones, maquinaria y armas."},"case_context":{"pt":"O caso combina extração florestal ilegal, abertura de acessos clandestinos e ocupação irregular de terra pública, indicando que futuras camadas de estradas/ramais e desmatamento podem acrescentar contexto espacial relevante.","en":"The case combines illegal forest extraction, clandestine access roads and irregular occupation of public land, showing how future road/track and deforestation layers can add useful spatial context.","es":"El caso combina extracción forestal ilegal, apertura de accesos clandestinos y ocupación irregular de tierra pública, mostrando cómo futuras capas de caminos y deforestación pueden aportar contexto espacial."},"primary_crime_type":"ILLEGAL_LOGGING","crime_types":["ILLEGAL_LOGGING","ILLEGAL_DEFORESTATION","LAND_GRABBING","PROTECTED_AREA_INVASION"],"operation_name":"Ukarãngmã","agencies":["Polícia Federal"],"occurred_at":"2026-08-13T16:50:00-03:00","published_at":"2026-08-14T16:50:00-03:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official investigation and enforcement event; no inference of guilt.","priority":"HIGH","location":{"name":"Terra Indígena Cachoeira Seca","admin1":"Pará","country":"Brasil","lat":-4.35,"lon":-52.37,"precision":"indigenous_land_approximate"},"protected_area":{"is_protected_area":true,"name":"Terra Indígena Cachoeira Seca"},"impacts":{"indigenous_or_local_communities":true},"cross_border":false,"keywords":["madeira","desmatamento","ramais clandestinos","terra indígena"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-cumpre-oito-mandados-de-busca-e-apreensao-em-terra-indigena","published_at":"2026-08-14T16:50:00-03:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-cumpre-oito-mandados-de-busca-e-apreensao-em-terra-indigena/whatsapp-image-2026-08-14-at-16-33-48.jpeg/@@images/b56147d3-92db-44ae-ae3a-febc786703f6.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF na matéria da Operação Ukarãngmã.","en":"Image published by Federal Police in the Operation Ukarãngmã report.","es":"Imagen publicada por la Policía Federal en la nota de la Operación Ukarãngmã."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

