INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-PA-2026-0807-EXTRACTIO-II','ILLEGAL_MINING',ARRAY['ILLEGAL_MINING']::text[],'CONFIRMED','HIGH','Federal Extractio II — 4ª fase','2026-08-06T18:45:00-03:00','2026-08-07T18:45:00-03:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Projeto Barão / Serra Dourada','Pará','Brasil',-6.4966,-49.8771,'municipality_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-desarticula-garimpo-ilegal-em-canaa-dos-carajas-durante-operacao-integrada','a2263bbd74ef30a653add652ab6f566e7b1545929aa466d0ba0639ae924bd0ce','{"id":"BR-PA-2026-0807-EXTRACTIO-II","title":{"pt":"Operação Federal Extractio II combate garimpo ilegal em Canaã dos Carajás","en":"Federal Extractio II targets illegal mining in Canaã dos Carajás","es":"Operación Federal Extractio II combate la minería ilegal en Canaã dos Carajás"},"summary":{"pt":"Operação integrada contra extração ilegal de ouro e cobre no Projeto Barão/Serra Dourada inutilizou e apreendeu maquinário, desmontou seis acampamentos e localizou explosivos, combustível e outros materiais.","en":"An integrated operation against illegal gold and copper extraction in the Barão/Serra Dourada area disabled and seized machinery, dismantled six camps and located explosives, fuel and other materials.","es":"Una operación integrada contra la extracción ilegal de oro y cobre en el área Barão/Serra Dourada inutilizó e incautó maquinaria, desmanteló seis campamentos y localizó explosivos, combustible y otros materiales."},"case_context":{"pt":"O caso mostra a infraestrutura logística associada à mineração clandestina, incluindo escavadeiras, geradores, motores, combustível e explosivos. Esses elementos podem futuramente alimentar uma camada própria de apreensões e infraestrutura de garimpo.","en":"The case illustrates the logistics supporting clandestine mining, including excavators, generators, engines, fuel and explosives. These elements can later feed dedicated seizure and mining-infrastructure layers.","es":"El caso muestra la infraestructura logística asociada a la minería clandestina, incluyendo excavadoras, generadores, motores, combustible y explosivos. Estos elementos podrán alimentar futuras capas de incautaciones e infraestructura minera."},"primary_crime_type":"ILLEGAL_MINING","crime_types":["ILLEGAL_MINING"],"operation_name":"Federal Extractio II — 4ª fase","agencies":["Polícia Federal","ICMBio","Ibama","Força Nacional"],"occurred_at":"2026-08-06T18:45:00-03:00","published_at":"2026-08-07T18:45:00-03:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official enforcement event; no inference of guilt.","priority":"HIGH","location":{"name":"Projeto Barão / Serra Dourada","admin1":"Pará","country":"Brasil","lat":-6.4966,"lon":-49.8771,"precision":"municipality_approximate"},"protected_area":{"is_protected_area":false},"impacts":{"indigenous_or_local_communities":false},"cross_border":false,"keywords":["ouro","cobre","escavadeira","explosivos","acampamentos"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-desarticula-garimpo-ilegal-em-canaa-dos-carajas-durante-operacao-integrada","published_at":"2026-08-07T18:45:00-03:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-desarticula-garimpo-ilegal-em-canaa-dos-carajas-durante-operacao-integrada/whatsapp-image-2026-08-07-at-18-26-35-1.jpeg/@@images/4435c668-d733-4232-b1a9-5b1fb2199508.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF na Operação Federal Extractio II.","en":"Image published by Federal Police for Federal Extractio II.","es":"Imagen publicada por la Policía Federal para Federal Extractio II."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

