INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-PA-2026-0806-SANTA-MARIA-BARREIRAS','ILLEGAL_MINING',ARRAY['ILLEGAL_MINING']::text[],'CONFIRMED','MEDIUM','Ação PF — Santa Maria das Barreiras','2026-08-05T18:00:00-03:00','2026-08-06T09:03:00-03:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Santa Maria das Barreiras','Pará','Brasil',-8.8578,-49.7215,'municipality_centroid_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-desativa-tres-pontos-de-garimpo-ilegal-no-para','3396a19fa265739b6ff69dee21f17d484a70f2b864adeb8fc5db7d683fca31d0','{"id":"BR-PA-2026-0806-SANTA-MARIA-BARREIRAS","title":{"pt":"PF desativa três pontos de garimpo ilegal em Santa Maria das Barreiras","en":"Federal Police shuts down three illegal mining sites in Santa Maria das Barreiras","es":"La Policía Federal desactiva tres puntos de minería ilegal en Santa Maria das Barreiras"},"summary":{"pt":"A PF informou o desmantelamento de três frentes de extração mineral clandestina, com apreensão de três escavadeiras hidráulicas e inutilização de estruturas de apoio.","en":"Federal Police reported dismantling three clandestine mining fronts, seizing three hydraulic excavators and disabling supporting infrastructure.","es":"La Policía Federal informó el desmantelamiento de tres frentes de extracción mineral clandestina, con incautación de tres excavadoras hidráulicas e inutilización de infraestructura de apoyo."},"case_context":{"pt":"O registro é útil para acompanhar a persistência de frentes mecanizadas de mineração ilegal no sul do Pará. O ponto cartográfico representa o município porque a fonte pública não divulga coordenadas exatas.","en":"The record helps track persistent mechanized illegal mining fronts in southern Pará. The map point represents the municipality because the public source does not disclose exact coordinates.","es":"El registro ayuda a seguir la persistencia de frentes mecanizados de minería ilegal en el sur de Pará. El punto del mapa representa el municipio porque la fuente pública no divulga coordenadas exactas."},"primary_crime_type":"ILLEGAL_MINING","crime_types":["ILLEGAL_MINING"],"operation_name":"Ação PF — Santa Maria das Barreiras","agencies":["Polícia Federal"],"occurred_at":"2026-08-05T18:00:00-03:00","published_at":"2026-08-06T09:03:00-03:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official enforcement event; no inference of guilt.","priority":"MEDIUM","location":{"name":"Santa Maria das Barreiras","admin1":"Pará","country":"Brasil","lat":-8.8578,"lon":-49.7215,"precision":"municipality_centroid_approximate"},"protected_area":{"is_protected_area":false},"impacts":{"indigenous_or_local_communities":false},"cross_border":false,"keywords":["escavadeiras","mineração","sul do Pará"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-desativa-tres-pontos-de-garimpo-ilegal-no-para","published_at":"2026-08-06T09:03:00-03:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-desativa-tres-pontos-de-garimpo-ilegal-no-para/18a06322-304f-4add-a9a8-be6fedebd314.jpg/@@images/b61947ad-0968-48e4-abf5-c54dd40c584f.jpeg","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF na fonte oficial do caso.","en":"Image published by Federal Police in the official source.","es":"Imagen publicada por la Policía Federal en la fuente oficial."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

