INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-PA-2026-0804-URUARA','ILLEGAL_DEFORESTATION',ARRAY['ILLEGAL_DEFORESTATION','ENVIRONMENTAL_CONTAMINATION','LAND_GRABBING']::text[],'CONFIRMED','URGENT','Operação PF — Uruará','2026-08-04T08:46:00-03:00','2026-08-04T08:46:00-03:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Uruará','Pará','Brasil',-3.7157,-53.7395,'municipality_centroid_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-deflagra-operacao-contra-grupo-suspeito-de-destruir-mais-de-10-mil-hectares-de-floresta-amazonica','56cfecc00877d459bf5a9d95e11e623fa01b9c02916801159bdd1949e547291e','{"id":"BR-PA-2026-0804-URUARA","title":{"pt":"PF investiga destruição de mais de 10 mil hectares de floresta em Uruará","en":"Federal Police investigates destruction of more than 10,000 hectares of forest in Uruará","es":"La Policía Federal investiga la destrucción de más de 10.000 hectáreas de bosque en Uruará"},"summary":{"pt":"Laudos periciais citados pela PF apontaram 10.180 hectares de floresta degradados por herbicidas em assentamentos federais de Uruará e, posteriormente, cerca de 5.794 hectares submetidos a corte raso e convertidos em pastagens. O dano foi estimado em R$ 469 milhões.","en":"Forensic reports cited by Federal Police indicated 10,180 hectares of forest degraded with herbicides in federal settlements in Uruará and later about 5,794 hectares clear-cut and converted to pasture. Damage was estimated at R$469 million.","es":"Informes periciales citados por la Policía Federal señalaron 10.180 hectáreas de bosque degradadas con herbicidas en asentamientos federales de Uruará y, después, unas 5.794 hectáreas taladas a ras y convertidas en pastizales. El daño se estimó en R$469 millones."},"case_context":{"pt":"O padrão descrito pela investigação associa degradação química da vegetação, corte raso e conversão para pastagem. A informação é de investigação oficial e não implica condenação dos investigados.","en":"The investigation describes a pattern linking chemical degradation of vegetation, clear-cutting and conversion to pasture. This is official investigative information and does not imply conviction of those investigated.","es":"La investigación describe un patrón que vincula degradación química de la vegetación, tala rasa y conversión a pastizales. Es información oficial de una investigación y no implica condena de los investigados."},"primary_crime_type":"ILLEGAL_DEFORESTATION","crime_types":["ILLEGAL_DEFORESTATION","ENVIRONMENTAL_CONTAMINATION","LAND_GRABBING"],"operation_name":"Operação PF — Uruará","agencies":["Polícia Federal"],"occurred_at":"2026-08-04T08:46:00-03:00","published_at":"2026-08-04T08:46:00-03:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official investigation; no inference of guilt or conviction.","priority":"URGENT","location":{"name":"Uruará","admin1":"Pará","country":"Brasil","lat":-3.7157,"lon":-53.7395,"precision":"municipality_centroid_approximate"},"protected_area":{"is_protected_area":false},"impacts":{"indigenous_or_local_communities":false},"cross_border":false,"keywords":["herbicidas","corte raso","pastagem","assentamentos","desmatamento"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-deflagra-operacao-contra-grupo-suspeito-de-destruir-mais-de-10-mil-hectares-de-floresta-amazonica","published_at":"2026-08-04T08:46:00-03:00","source_type":"official"}],"source_media":[]}'::jsonb) ON CONFLICT (id) DO NOTHING;

INSERT INTO event_sources (event_id,publisher,url,published_at,source_type) VALUES ('BR-PA-2026-0804-URUARA','Polícia Federal','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-deflagra-operacao-contra-grupo-suspeito-de-destruir-mais-de-10-mil-hectares-de-floresta-amazonica','2026-08-04T08:46:00-03:00','official') ON CONFLICT (event_id,url) DO NOTHING;

INSERT INTO events (id,primary_crime_type,crime_types,validation_status,priority,operation_name,occurred_at,published_at,added_at,updated_at,backfill,location_name,admin1,country,lat,lon,location_precision,canonical_url,fingerprint,payload) VALUES ('BR-RO-MT-2026-0804-FORTUNA','ILLEGAL_MINING',ARRAY['ILLEGAL_MINING','PROTECTED_AREA_INVASION']::text[],'CONFIRMED','HIGH','Fortuna','2026-08-03T12:00:00-04:00','2026-08-04T10:59:00-04:00','2026-09-16T00:55:00+07:00','2026-09-16T00:55:00+07:00',TRUE,'Terra Indígena Sete de Setembro','Rondônia / Mato Grosso','Brasil',-11.17,-61.15,'indigenous_land_approximate','https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-e-ibama-combatem-garimpo-ilegal-em-terra-indigena-sediada-em-dois-estados','305846d8e5dea833d5b4653237002ade0797e529815cdd752ae6fdc285207fed','{"id":"BR-RO-MT-2026-0804-FORTUNA","title":{"pt":"Operação Fortuna combate garimpo ilegal na TI Sete de Setembro","en":"Operation Fortuna targets illegal mining in Sete de Setembro Indigenous Land","es":"Operación Fortuna combate la minería ilegal en la TI Sete de Setembro"},"summary":{"pt":"PF e Ibama localizaram e inutilizaram duas motocicletas, dois motores, um gerador, uma balsa e 11 acampamentos usados na logística de garimpo na Terra Indígena Sete de Setembro, entre Rondônia e Mato Grosso.","en":"Federal Police and Ibama located and disabled two motorcycles, two engines, a generator, a barge and 11 camps used to support illegal mining in Sete de Setembro Indigenous Land across Rondônia and Mato Grosso.","es":"La Policía Federal e Ibama localizaron e inutilizaron dos motocicletas, dos motores, un generador, una balsa y 11 campamentos usados en la logística de minería ilegal en la Tierra Indígena Sete de Setembro, entre Rondônia y Mato Grosso."},"case_context":{"pt":"O caso evidencia a dimensão logística do garimpo em terra indígena e atravessa a divisa estadual RO–MT. A posição no mapa é aproximada e representa a área indígena, não os 11 acampamentos individualmente.","en":"The case highlights the logistics of illegal mining in Indigenous land and crosses the RO–MT state boundary. The map position is approximate and represents the Indigenous territory, not the 11 camps individually.","es":"El caso evidencia la dimensión logística de la minería ilegal en tierra indígena y cruza el límite RO–MT. La posición en el mapa es aproximada y representa el territorio indígena, no los 11 campamentos individualmente."},"primary_crime_type":"ILLEGAL_MINING","crime_types":["ILLEGAL_MINING","PROTECTED_AREA_INVASION"],"operation_name":"Fortuna","agencies":["Polícia Federal","Ibama"],"occurred_at":"2026-08-03T12:00:00-04:00","published_at":"2026-08-04T10:59:00-04:00","added_at":"2026-09-16T00:55:00+07:00","updated_at":"2026-09-16T00:55:00+07:00","backfill":true,"validation_status":"CONFIRMED","legal_status_note":"Official enforcement event; no inference of guilt.","priority":"HIGH","location":{"name":"Terra Indígena Sete de Setembro","admin1":"Rondônia / Mato Grosso","country":"Brasil","lat":-11.17,"lon":-61.15,"precision":"indigenous_land_approximate"},"protected_area":{"is_protected_area":true,"name":"Terra Indígena Sete de Setembro"},"impacts":{"indigenous_or_local_communities":true},"cross_border":false,"keywords":["garimpo","acampamentos","balsa","terra indígena"],"sources":[{"publisher":"Polícia Federal","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-e-ibama-combatem-garimpo-ilegal-em-terra-indigena-sediada-em-dois-estados","published_at":"2026-08-04T10:59:00-04:00","source_type":"official"}],"source_media":[{"type":"image","url":"https://www.gov.br/pf/pt-br/assuntos/noticias/2026/08/pf-e-ibama-combatem-garimpo-ilegal-em-terra-indigena-sediada-em-dois-estados/captura-de-tela-2026-08-04-105558.png/@@images/6a3fcbd6-006b-49f8-be21-a9bfac2c6a15.png","credit":"Polícia Federal","caption":{"pt":"Imagem publicada pela PF na fonte oficial da Operação Fortuna.","en":"Image published by Federal Police in the official Operation Fortuna source.","es":"Imagen publicada por la Policía Federal en la fuente oficial de la Operación Fortuna."}}]}'::jsonb) ON CONFLICT (id) DO NOTHING;

